"""A private room-and-time observation board, not an HVAC diagnosis."""
import html
import shutil
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit
from editorial import write_editorial_page


def add(out, origin, pages, booking):
    root = out.parent
    for name in ('comfort-map.css', 'comfort-map.mjs'):
        shutil.copy(root / 'assets' / name, out / 'assets' / name)
    parts = urlsplit(booking)
    query = dict(parse_qsl(parts.query))
    query['utm_content'] = 'comfort-map'
    destination = html.escape(urlunsplit(parts._replace(query=urlencode(query))), quote=True)
    body = '''<div class="comfort-map" id="comfort-map">
<header class="wrap cm-hero"><div><a class="cm-back" href="/explore/">Wazoozie / useful things for your home</a><p class="cm-kicker">THE COMFORT MAP</p><h1>Same house.<br><em>Different story.</em></h1><p class="cm-lede">The bedroom’s cold. The living room’s fine.<br>Give the next service call a clearer picture.</p><p class="cm-intro">Mark how your rooms feel at different times. Leave with a simple room-by-room brief you can show a heating and cooling professional.</p><div class="cm-hero-actions"><a class="cm-primary" href="#cm-workbench">Map my rooms ↓</a><span>No account. No upload.<br>Start with one room.</span></div><p class="cm-direct">Already need service? <a href="tel:+16105006416">Call Middletown HVAC: 610-500-6416 ↗</a></p></div>
<div class="cm-cover" aria-label="Illustrative comfort map, not your home’s results"><div class="cm-cover-top"><span>A LITTLE MORE THAN<br>“IT DOESN’T FEEL RIGHT.”</span><b aria-hidden="true">w.</b></div><div class="cm-mini-map" aria-hidden="true"><div class="cm-mini-room cm-mini-cool"><span>UPSTAIRS</span><strong>A bit chilly.</strong><i>−</i></div><div class="cm-mini-room cm-mini-okay"><span>DOWNSTAIRS</span><strong>Just right.</strong><i>○</i></div><div class="cm-mini-room cm-mini-warm"><span>AFTERNOON</span><strong>Too warm.</strong><i>+</i></div></div><p>One thermostat can’t tell<br>the whole story.</p><small>Illustration only. Your map starts blank.</small></div></header>
<section class="wrap cm-workbench" id="cm-workbench" aria-labelledby="cm-title"><div class="cm-section-top"><div><p class="cm-kicker">OBSERVE. DON’T GUESS.</p><h2 id="cm-title">How does each room feel?</h2><p>Use your own experience. “Not observed” is a useful answer. You do not need to wait a full day or fill every box before calling.</p></div><span class="cm-private">Stays in this open page</span></div>
<details class="cm-safety"><summary>When to stop here and get urgent help</summary><p>For a gas odor, a Carbon Monoxide alarm, smoke, fire or electrical arcing, leave the affected area. Contact emergency services or your utility from a safe location. Do not reset equipment or re-enter until the appropriate professionals say it is safe. This map does not assess safety.</p><p>If heating or cooling has stopped working, call the business to discuss service. Do not delay getting help to complete this map.</p></details>
<div id="cm-app" hidden><div class="cm-context"><label>What does this map describe?<select id="cm-basis"><option value="pattern">A pattern I remember</option><option value="day">Observations from one day</option></select></label><label id="cm-date-label" hidden>Which day? <span>(optional)</span><input type="date" id="cm-date"></label><label>System while observing<select id="cm-mode"><option value="unknown">Not sure / varies</option><option value="heat">Heating</option><option value="cool">Cooling</option><option value="off">Off</option></select></label><label>When did you first notice it?<select id="cm-duration"><option value="unknown">Not sure</option><option value="recent">Recently</option><option value="recurring">It comes and goes</option><option value="longstanding">It has been this way for a while</option></select></label></div>
<div class="cm-layout"><section class="cm-board" aria-labelledby="cm-rooms-title"><div class="cm-board-heading"><h3 id="cm-rooms-title">Your rooms</h3><span id="cm-room-count">2 of 6 rooms</span></div><p class="cm-board-note">Optional names stay here too. Skip addresses and personal details.</p><div id="cm-rooms"></div><button type="button" class="cm-add" id="cm-add">+ Add another room</button><label class="cm-notes-label" for="cm-notes">Anything else you noticed? <span>(optional)</span></label><textarea id="cm-notes" maxlength="1500" rows="3" placeholder="Example: bedroom door was closed, afternoon sun, thermostat setting, or a recent change."></textarea><p class="cm-observe-only">Observe during normal use only. Don’t open equipment, enter restricted spaces, adjust dampers or change how the system runs to fill this out.</p></section>
<aside class="cm-story" aria-labelledby="cm-story-title"><p class="cm-kicker">THE STORY SO FAR</p><h3 id="cm-story-title">Start with what you notice.</h3><p id="cm-count" class="cm-count">No observations yet.</p><div id="cm-picture" class="cm-picture"></div><ul id="cm-findings"></ul><div class="cm-next-question"><span>ONE GOOD QUESTION</span><p id="cm-question">“What would you need to check to understand the comfort in these rooms?”</p></div><p class="cm-boundary">This summarizes your entries. It does not measure temperature, find a cause, size equipment or recommend a repair or replacement.</p><a class="cm-sheet-jump" href="#cm-takeaway">Take this to the conversation ↓</a></aside></div>
<section class="cm-takeaway" id="cm-takeaway" aria-labelledby="cm-takeaway-title"><div><p class="cm-kicker">A BETTER START TO THE VISIT.</p><h2 id="cm-takeaway-title">Bring the rooms<br>into the conversation.</h2><p>Your brief includes the observations you entered, what you haven’t checked and a few questions to ask. Review it before copying, downloading or sharing.</p><details class="cm-preview"><summary>Read my visit brief</summary><pre id="cm-brief"></pre></details><div class="cm-actions"><button type="button" class="cm-primary" id="cm-copy">Copy my brief</button><button type="button" class="cm-secondary" id="cm-download">Download my brief</button><button type="button" class="cm-secondary" id="cm-print">Print / save PDF</button></div><label id="cm-copy-fallback" hidden>Copy this brief<textarea id="cm-copy-text" readonly rows="9"></textarea></label><p id="cm-status" role="status" aria-live="polite"></p></div>
<aside class="cm-contact"><p class="cm-kicker">A LOCAL NEXT STEP</p><h3>Talk it through<br>with Middletown HVAC.</h3><p>Ask about a visit for uneven heating or cooling. Confirm coverage for your address, availability and any visit charge directly.</p><a class="cm-contact-call" href="tel:+16105006416">Call 610-500-6416 ↗</a><a class="cm-contact-book" href="BOOKING_DESTINATION" target="_blank" rel="noopener noreferrer">Open Middletown’s booking page ↗</a><a class="cm-contact-profile" href="/businesses/middletown-hvac/">Read the business profile →</a><p class="cm-contact-note">Your map is not sent with these links. Save a copy first, then share it directly if you choose. Opening a booking page does not confirm an appointment.</p><p class="cm-contact-note">Middletown is a featured Wazoozie listing. This placement is editorial, not a diagnosis or a comparison of contractors. <a href="/how-it-works/">How Wazoozie works</a>.</p></aside></section>
<div class="cm-privacy"><p>Entries stay in this open page only. No account, browser storage, upload or automatic inquiry. Refreshing clears them; leaving may discard them. Copy or download anything you want to keep. The website host still receives ordinary page requests; <a href="/privacy/">read the privacy notice</a>.</p><button type="button" id="cm-clear" class="cm-text-button">Clear my map</button></div><div id="cm-clear-confirm" class="cm-clear-confirm" hidden><p>Clear every room and note? Download a copy first if you want to keep this map.</p><button type="button" id="cm-clear-yes" class="cm-secondary">Yes, clear the map</button><button type="button" id="cm-clear-no" class="cm-text-button">Keep my entries</button></div>
<details class="cm-method"><summary>How this works, and what it cannot tell you</summary><p>The map is a fixed, browser-only tool. It counts only the feelings you select and describes differences between those entries. Blank cells remain “Not observed,” never “Feels okay.” The color tiles are a visual key to your answers, not measured temperatures or a floor plan. Different people, days, weather and thermostat settings can change the experience.</p><p>The conversation questions encourage a professional to evaluate the home before proposing work. <a href="https://www.energystar.gov/saveathome/heating-cooling/hvac-quality-installation" target="_blank" rel="noopener noreferrer">ENERGY STAR’s quality-installation guidance</a> discusses home-specific equipment sizing, system airflow and duct evaluation. This map does not perform those assessments, and ENERGY STAR does not endorse this tool or any listed business.</p><p>No model service or chatbot is used. There is no comfort score, quotation, diagnosis, live technician availability or promise that a particular service will fix the problem.</p></details></div>
<noscript><div class="cm-no-script"><h3>Make a simple room-by-room note.</h3><p>Write down the room, when it feels too warm or too cool, what the thermostat is set to if you know, and any recent change. Ask a professional what they would check before recommending work. JavaScript enables the private map, but it is not required to <a href="tel:+16105006416">call Middletown HVAC at 610-500-6416</a> or <a href="/businesses/middletown-hvac/">read its profile</a>.</p></div></noscript>
</section><section id="cm-print-sheet" class="cm-print-sheet" aria-hidden="true"><h2>The Comfort Map</h2><pre id="cm-print-text"></pre></section></div>'''.replace('BOOKING_DESTINATION', destination)
    write_editorial_page(out, origin, pages, '/comfort-map/', 'The Comfort Map — a clearer HVAC conversation', 'Map how your rooms feel across the day. Keep a private, room-by-room observation brief for a heating and cooling visit. No diagnosis, upload or account.', body)
    target = out / 'comfort-map/index.html'
    target.write_text(target.read_text().replace('</head>', '<link rel="stylesheet" href="/assets/comfort-map.css"></head>', 1).replace('</body>', '<script type="module" src="/assets/comfort-map.mjs"></script></body>', 1))
    promo = '''<section class="wrap cm-promo" aria-labelledby="cm-promo-title"><div><p class="cm-kicker">NEW / THE COMFORT MAP</p><h2 id="cm-promo-title">Same house.<br>Different story.</h2><p>A chilly bedroom. A warm upstairs. Map the rooms that feel different and take a clearer picture to your next HVAC conversation.</p><a href="/comfort-map/">Make my private comfort map →</a></div><div class="cm-promo-tiles" aria-hidden="true"><span>TOO COOL <b>−</b></span><span>FEELS OKAY <b>○</b></span><span>TOO WARM <b>+</b></span></div></section>'''
    # Append through an isolated enhancement rather than changing existing generators.
    for relative in ('explore/index.html', 'services/heating-cooling/index.html', 'services/second-opinion/index.html', 'businesses/middletown-hvac/index.html'):
        path = out / relative
        path.write_text(path.read_text().replace('</main>', promo + '</main>', 1).replace('</head>', '<link rel="stylesheet" href="/assets/comfort-map.css"></head>', 1))
    privacy = out / 'privacy/index.html'
    privacy.write_text(privacy.read_text().replace('</main>', '<section class="wrap project-inline"><h2>The Comfort Map.</h2><p>Room names, selections and notes remain in the open page only. They are not saved in browser storage, submitted to Wazoozie or included in business links. Copying places the brief on your device clipboard; downloading creates a plain-text file; printing uses your browser. These copies include your entries. Share them only with the people you choose. Refreshing clears the map; leaving may discard it.</p></section></main>', 1))
